-- Draft sales and demand planning; depends on 001–006.
begin;
create table erp.channels(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, location_id uuid unique not null references erp.locations);
create table erp.customers(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, legacy_cafe_id uuid unique references public.cafes, active boolean not null default true);
create table erp.price_lists(id uuid primary key default gen_random_uuid(), code text unique not null, channel_id uuid references erp.channels, name text not null);
create table erp.price_list_lines(id uuid primary key default gen_random_uuid(), list_id uuid not null references erp.price_lists, item_id uuid not null references erp.items, price numeric(24,8) not null check(price>=0), effective_from timestamptz not null, unique(list_id,item_id,effective_from));
create table erp.sales_orders(id uuid primary key default gen_random_uuid(), code text unique not null, channel_id uuid not null references erp.channels, customer_id uuid not null references erp.customers, distributor_id uuid references public.distributors, external_ref text, status text not null default 'draft' check(status in ('draft','confirmed','partial','delivered','cancelled')), unique(channel_id,external_ref));
create table erp.sales_order_lines(id uuid primary key default gen_random_uuid(), order_id uuid not null references erp.sales_orders, item_id uuid not null references erp.items, quantity numeric(18,6) not null check(quantity>0), unit_price numeric(24,8) not null check(unit_price>=0), discount numeric(24,8) not null default 0 check(discount>=0 and discount<=quantity*unit_price));
create table erp.deliveries(id uuid primary key default gen_random_uuid(), order_id uuid not null references erp.sales_orders, stock_document_id uuid unique references erp.stock_documents);
create table erp.delivery_lines(id uuid primary key default gen_random_uuid(), delivery_id uuid not null references erp.deliveries, order_line_id uuid not null references erp.sales_order_lines, quantity numeric(18,6) not null check(quantity>0));
create table erp.sales_invoices(id uuid primary key default gen_random_uuid(), code text unique not null, order_id uuid not null references erp.sales_orders, journal_entry_id uuid unique references erp.journal_entries, invoice_date date not null);
create table erp.sales_invoice_lines(id uuid primary key default gen_random_uuid(), invoice_id uuid not null references erp.sales_invoices, delivery_line_id uuid not null references erp.delivery_lines, quantity numeric(18,6) not null check(quantity>0), net_amount numeric(24,8) not null check(net_amount>=0), commission_amount numeric(24,8) not null default 0 check(commission_amount>=0));
create table erp.customer_payment_allocations(voucher_id uuid references erp.vouchers, invoice_id uuid references erp.sales_invoices, amount numeric(24,8) not null check(amount>0), primary key(voucher_id,invoice_id));
create table erp.sales_returns(id uuid primary key default gen_random_uuid(), code text unique not null, invoice_id uuid not null references erp.sales_invoices, stock_document_id uuid unique references erp.stock_documents, journal_entry_id uuid unique references erp.journal_entries, refund_voucher_id uuid references erp.vouchers, reason text not null);
create table erp.sales_return_lines(id uuid primary key default gen_random_uuid(), return_id uuid not null references erp.sales_returns, invoice_line_id uuid not null references erp.sales_invoice_lines, quantity numeric(18,6) not null check(quantity>0), refund_amount numeric(24,8) not null check(refund_amount>=0));
create table erp.replenishment_rules(item_id uuid references erp.items, location_id uuid references erp.locations, safety_stock numeric(18,6) not null check(safety_stock>=0), reorder_point numeric(18,6) not null, target_stock numeric(18,6) not null, maximum_stock numeric(18,6) not null, lead_days integer not null check(lead_days>=0), primary key(item_id,location_id), check(safety_stock<=reorder_point and reorder_point<=target_stock and target_stock<=maximum_stock));
create table erp.planning_runs(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), horizon_end date not null);
create table erp.planning_suggestions(id uuid primary key default gen_random_uuid(), run_id uuid not null references erp.planning_runs, item_id uuid not null references erp.items, location_id uuid not null references erp.locations, kind text not null check(kind in ('purchase','manufacture','transfer')), quantity numeric(18,6) not null check(quantity>0), required_on date not null, status text not null default 'proposed' check(status in ('proposed','approved','converted','rejected')));
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='erp' loop execute format('alter table erp.%I enable row level security',t.tablename); end loop; end $$;
commit;
-- Required: reservation linkage, channel isolation, invoice and delivery limits,
-- commission reversals, distributor custody/refund funding, external order idempotency,
-- BOM explosion and net requirements calculation before use.
